package io.github.capozziv.digitalbanking.accounts.bootstrap

import io.github.capozziv.digitalbanking.accounts.bootstrap.web.ApiClient
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.web.server.LocalServerPort
import org.springframework.http.HttpMethod
import tools.jackson.databind.JsonNode
import tools.jackson.databind.json.JsonMapper
import java.net.URI
import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse

/** The OpenAPI contract generated by springdoc documents the seven operations of the spec and their errors. */
class OpenApiIT : AccountsIntegrationTest() {
    @LocalServerPort
    private var port: Int = 0

    private val docs: JsonNode by lazy {
        val response = ApiClient(port).get("/v3/api-docs")
        assertThat(response.status).describedAs(response.rawBody).isEqualTo(200)
        response.body!!
    }

    @Test
    fun `the contract has exactly the seven paths and methods of the spec`() {
        val paths = docs.get("paths")
        val operations =
            paths.propertyNames().flatMap { path -> paths.get(path).propertyNames().map { method -> "${method.uppercase()} $path" } }

        assertThat(operations).containsExactlyInAnyOrder(
            "POST /accounts",
            "GET /accounts/{id}",
            "POST /accounts/{id}/credits",
            "POST /accounts/{id}/debits",
            "PUT /accounts/{id}/type",
            "GET /admin/account-types",
            "PUT /admin/account-types/{type}",
        )
    }

    @Test
    fun `every operation documents 500 internal-error as Problem Details`() {
        for ((name, operation) in operations()) {
            val internalError = operation.get("responses").get("500")
            assertThat(internalError).describedAs(name).isNotNull()
            assertThat(internalError.get("content").get("application/problem+json")).describedAs(name).isNotNull()
            assertThat(internalError.get("description").asString()).describedAs(name).contains("/problems/internal-error")
        }
    }

    @Test
    fun `the operations with Idempotency-Key require it and document 400 missing-idempotency-key checked before the body`() {
        for (name in listOf("POST /accounts", "POST /accounts/{id}/credits", "POST /accounts/{id}/debits")) {
            val operation = operation(name)
            val header =
                operation.get("parameters").single { it.get("in").asString() == "header" && it.get("name").asString() == "Idempotency-Key" }

            assertThat(header.get("required").asBoolean()).describedAs(name).isTrue()
            assertThat(
                header.get("description").asString(),
            ).describedAs(name).contains("missing-idempotency-key").contains("before the body")
            assertThat(
                operation
                    .get("responses")
                    .get("400")
                    .get("description")
                    .asString(),
            ).describedAs(name)
                .contains("/problems/missing-idempotency-key")
                .contains("/problems/validation-error")
        }
    }

    @Test
    fun `the operations that lock the account document 503 account-busy with a Retry-After header`() {
        for (name in listOf("POST /accounts/{id}/credits", "POST /accounts/{id}/debits", "PUT /accounts/{id}/type")) {
            val busy = operation(name).get("responses").get("503")

            assertThat(busy).describedAs(name).isNotNull()
            assertThat(busy.get("description").asString()).describedAs(name).contains("/problems/account-busy")
            assertThat(busy.get("headers").get("Retry-After")).describedAs(name).isNotNull()
        }
    }

    @Test
    fun `the debit documents 422 insufficient-available-balance and idempotency-key-reused`() {
        val unprocessable =
            operation("POST /accounts/{id}/debits")
                .get("responses")
                .get("422")
                .get("description")
                .asString()

        assertThat(unprocessable).contains("/problems/insufficient-available-balance").contains("/problems/idempotency-key-reused")
    }

    @Test
    fun `the contract says that framework errors such as 405, 415 and unknown routes have type about-blank`() {
        val description = docs.get("info").get("description").asString()

        assertThat(description)
            .contains("about:blank")
            .contains("405")
            .contains("415")
            .contains("404")
    }

    @Test
    fun `the entry description documents its maximum length and the refusal of control characters`() {
        val description =
            docs
                .get("components")
                .get("schemas")
                .get("RecordEntryRequest")
                .get("properties")
                .get("description")

        assertThat(description.get("maxLength").asInt()).isEqualTo(140)
        assertThat(description.get("pattern").asString()).isEqualTo("[^\\x00-\\x1F]*")
    }

    @Test
    fun `the ProblemDetail schema referenced by the error responses exists`() {
        assertThat(docs.get("components").get("schemas").get("ProblemDetail")).isNotNull()
    }

    @Test
    fun `framework errors really are Problem Details without type, that is about-blank`() {
        val api = ApiClient(port)
        val unknownRoute = api.get("/nowhere").let { it.status to it.rawBody }
        val methodNotAllowed = api.send(HttpMethod.DELETE, "/admin/account-types").let { it.status to it.rawBody }
        val unsupportedMediaType = putPlainText("/admin/account-types/FREE")

        for ((expected, actual) in listOf(404 to unknownRoute, 405 to methodNotAllowed, 415 to unsupportedMediaType)) {
            val (status, body) = actual
            assertThat(status).describedAs(body).isEqualTo(expected)
            val problem = mapper.readTree(body)
            assertThat(problem.get("status").asInt()).isEqualTo(expected)
            val type = problem.get("type")
            assertThat(type == null || type.asString() == "about:blank").describedAs(body).isTrue()
        }
    }

    private val mapper = JsonMapper.builder().build()

    /** The ApiClient always sends JSON; a text/plain body needs the JDK client. */
    private fun putPlainText(path: String): Pair<Int, String> {
        val request =
            HttpRequest
                .newBuilder(URI.create("http://localhost:$port$path"))
                .header("Content-Type", "text/plain")
                .PUT(HttpRequest.BodyPublishers.ofString("x"))
                .build()
        val response = HttpClient.newHttpClient().use { it.send(request, HttpResponse.BodyHandlers.ofString()) }
        return response.statusCode() to response.body()
    }

    private fun operations(): List<Pair<String, JsonNode>> {
        val paths = docs.get("paths")
        return paths.propertyNames().flatMap { path ->
            paths.get(path).propertyNames().map { method -> "${method.uppercase()} $path" to paths.get(path).get(method) }
        }
    }

    private fun operation(name: String): JsonNode = operations().single { it.first == name }.second
}
